import importlib.util
import random
from decimal import localcontext
from pricing import checkout
spec = importlib.util.spec_from_file_location('original', '.pricing_original.py')
original = importlib.util.module_from_spec(spec)
spec.loader.exec_module(original)
rng = random.Random(42)

def outcome(fn, cart, customer, coupon, precision):
    with localcontext() as context:
        context.prec = precision
        try:
            return ('result', repr(fn(cart, customer, coupon)))
        except Exception as exc:
            return ('error', type(exc), str(exc))

for i in range(15000):
    cart = []
    for j in range(rng.randrange(5)):
        item = {'sku': str(j), 'price': rng.choice(['0.005', '0.065', '3.33', '12.99', '-5.555', 0, 100, 'bad']), 'qty': rng.choice([-2, 0, 1, 9, 10, 11])}
