            item['category'] = rng.choice(['books', 'food', 'other', None, [], {}])
        cart.append(item)
    customer = {'tier': rng.choice(['silver', 'platinum', 'other', None, [], {}])}
    coupon = rng.choice([None, 'WELCOME5', 'HALFSHIP', 'PCT10', 'PCT35', 'PCT-5', 'PCTbad', 'other'])
    precision = rng.choice([1, 2, 3, 6, 28])
    expected = outcome(original.checkout, cart, customer, coupon, precision)
    actual = outcome(checkout, cart, customer, coupon, precision)
